        update: regularTransition,
        leave: leaveTransition,
        config: springConfig,
        immediate: !animate,
    })

    return (
        <>
            {transition((animatedProps, link) =>
                createElement(linkComponent, {
                    link,
                    linkGenerator,
                    animatedProps,
                    isInteractive,
                    onMouseEnter,
                    onMouseMove,
                    onMouseLeave,
                    onMouseDown,
                    onMouseUp,
                    onClick,
                    onDoubleClick,
                    tooltip,
                    tooltipAnchor,
                })
            )}
        </>
    )
};

