const renderNode = <Datum>(
    ctx: CanvasRenderingContext2D,
    { node }: NodeCanvasRendererProps<Datum>
) => {
    ctx.beginPath()
    ctx.arc(node.x, node.y, node.size / 2, 0, 2 * Math.PI)
    ctx.fillStyle = node.color
    ctx.fill()
};

